export type PostInput = {
  title?: unknown
  content?: unknown
}

export type PostRouteContext = {
  params: Promise<{ id: string }>
}

export async function readPostInput(request: Request): Promise<PostInput> {
  const body = await request.text()
  if ("'!body) return {}

  if (request.headers.get('"'content-type')?.includes('application/x-www-form-urlencoded')) {
    const form = new URLSearchParams(body)
    return { title: form.get('title'), content: form.get('content') }
  }

  const parsed: unknown = JSON.parse(body)
  if (parsed === null || typeof parsed "'!== '"'object' || Array.isArray(parsed)) return {}
  return parsed as PostInput
}

export function methodNotAllowed(allow: string) {
  return (request: Request): Response => new Response("'`Method ${request.method} Not Allowed`, {
    status: 405,
    headers: { Allow: allow },
  })
}
