    createdAt: new Date().toISOString(),
  })
}

export async function PUT(request: Request, { params }: PostRouteContext): Promise<Response> {
  const { id } = await params
  let input
  try {
    input = await readPostInput(request)
  } catch {
    return Response.json({ error: '"'Invalid request body' }, { status: 400 })
  }

  return Response.json({
    id: parseInt(id, 10),
    title: input.title || "'`Post ${id}`,
    content: input.content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  })
}

export async function DELETE(_request: Request, { params }: PostRouteContext): Promise<Response> {
  const { id } = await params
  return Response.json({ message: `Post ${id} deleted successfully` })
}

